    dt_text = f"20{groups[0]}-{groups[1]}-{groups[2]}T{groups[3]}:{groups[4]}:{groups[5]}"
    dt = datetime.strptime(dt_text, '%Y-%m-%dT%H:%M:%S')
    return {'stored': [int(dt.timestamp() * 1000)], 'layout': []}

def inverse(record):
    ts = int(record['stored'][0])
    dt = datetime.fromtimestamp(ts / 1000)
    return f"{dt.strftime('%y/%m/%d %H:%M:%S')}"

